TITLE = "เสขปฏิปทาสูตร"
SUB = "มัชฌิมนิกาย มัชฌิมปัณณาสก์ (MN 53) · ข้อปฏิบัติของพระเสขะ (ผู้ยังต้องศึกษา)"
EXPAND = {
    "mn53:8.4": "Sotena saddaṁ sutvā na nimittaggāhī hoti nānubyañjanaggāhī. Yatvādhikaraṇamenaṁ sotindriyaṁ asaṁvutaṁ viharantaṁ abhijjhādomanassā pāpakā akusalā dhammā anvāssaveyyuṁ, tassa saṁvarāya paṭipajjati, rakkhati sotindriyaṁ, sotindriyaṁ saṁvaraṁ āpajjati.",
    "mn53:8.5": "ghānena gandhaṁ ghāyitvā na nimittaggāhī hoti nānubyañjanaggāhī. Yatvādhikaraṇamenaṁ ghānindriyaṁ asaṁvutaṁ viharantaṁ abhijjhādomanassā pāpakā akusalā dhammā anvāssaveyyuṁ, tassa saṁvarāya paṭipajjati, rakkhati ghānindriyaṁ, ghānindriyaṁ saṁvaraṁ āpajjati.",
    "mn53:8.6": "jivhāya rasaṁ sāyitvā na nimittaggāhī hoti nānubyañjanaggāhī. Yatvādhikaraṇamenaṁ jivhindriyaṁ asaṁvutaṁ viharantaṁ abhijjhādomanassā pāpakā akusalā dhammā anvāssaveyyuṁ, tassa saṁvarāya paṭipajjati, rakkhati jivhindriyaṁ, jivhindriyaṁ saṁvaraṁ āpajjati.",
    "mn53:8.7": "kāyena phoṭṭhabbaṁ phusitvā na nimittaggāhī hoti nānubyañjanaggāhī. Yatvādhikaraṇamenaṁ kāyindriyaṁ asaṁvutaṁ viharantaṁ abhijjhādomanassā pāpakā akusalā dhammā anvāssaveyyuṁ, tassa saṁvarāya paṭipajjati, rakkhati kāyindriyaṁ, kāyindriyaṁ saṁvaraṁ āpajjati.",
    "mn53:18.2": "Idha, mahānāma, ariyasāvako vivicceva kāmehi vivicca akusalehi dhammehi savitakkaṁ savicāraṁ vivekajaṁ pītisukhaṁ paṭhamaṁ jhānaṁ upasampajja viharati;",
    "mn53:18.3": "vitakkavicārānaṁ vūpasamā ajjhattaṁ sampasādanaṁ cetaso ekodibhāvaṁ avitakkaṁ avicāraṁ samādhijaṁ pītisukhaṁ dutiyaṁ jhānaṁ upasampajja viharati;",
    "mn53:18.4": "pītiyā ca virāgā upekkhako ca viharati sato ca sampajāno sukhañca kāyena paṭisaṁvedeti, yaṁ taṁ ariyā ācikkhanti ‘upekkhako satimā sukhavihārī’ti tatiyaṁ jhānaṁ upasampajja viharati;",
    "mn53:18.5": "sukhassa ca pahānā dukkhassa ca pahānā pubbeva somanassadomanassānaṁ atthaṅgamā adukkhamasukhaṁ upekkhāsatipārisuddhiṁ catutthaṁ jhānaṁ upasampajja viharati;",
    "mn53:20.2": "seyyathidaṁ—ekampi jātiṁ dvepi jātiyo tissopi jātiyo catassopi jātiyo pañcapi jātiyo dasapi jātiyo vīsampi jātiyo tiṁsampi jātiyo cattālīsampi jātiyo paññāsampi jātiyo jātisatampi jātisahassampi jātisatasahassampi anekepi saṁvaṭṭakappe anekepi vivaṭṭakappe anekepi saṁvaṭṭavivaṭṭakappe: ‘amutrāsiṁ evaṁnāmo evaṅgotto evaṁvaṇṇo evamāhāro evaṁsukhadukkhappaṭisaṁvedī evamāyupariyanto, so tato cuto amutra udapādiṁ; tatrāpāsiṁ evaṁnāmo evaṅgotto evaṁvaṇṇo evamāhāro evaṁsukhadukkhappaṭisaṁvedī evamāyupariyanto, so tato cuto idhūpapanno’ti iti sākāraṁ sauddesaṁ anekavihitaṁ pubbenivāsaṁ anussarati.",
    "mn53:21.1": "Sa kho so, mahānāma, ariyasāvako imaṁyeva anuttaraṁ upekkhāsatipārisuddhiṁ āgamma dibbena cakkhunā visuddhena atikkantamānusakena satte passati cavamāne upapajjamāne hīne paṇīte suvaṇṇe dubbaṇṇe sugate duggate yathākammūpage satte pajānāti.",
    "mn53:24.1": "Yañca kho, mahānāma, ariyasāvako anekavihitaṁ pubbenivāsaṁ anussarati, seyyathidaṁ—ekampi jātiṁ dvepi jātiyo …pe… iti sākāraṁ sauddesaṁ anekavihitaṁ pubbenivāsaṁ anussarati;",
    "mn53:24.2": "yampi, mahānāma, ariyasāvako dibbena cakkhunā visuddhena atikkantamānusakena satte passati cavamāne upapajjamāne hīne paṇīte suvaṇṇe dubbaṇṇe sugate duggate yathākammūpage satte pajānāti;",
}
TH = {
    "1": "ข้าพเจ้าได้ฟังมาอย่างนี้ สมัยหนึ่ง พระผู้มีพระภาคเจ้าประทับอยู่ที่นิโครธาราม ใกล้กรุงกบิลพัสดุ์ แคว้นสักกะ",
    "2": "ครั้งนั้น ศากยะชาวกบิลพัสดุ์ได้สร้างสัณฐาคาร (ศาลาที่ประชุม) ใหม่ ยังไม่มีสมณะหรือพราหมณ์เข้าไปใช้ "
         "จึงเข้าเฝ้าพระผู้มีพระภาคเจ้า กราบแล้วนั่งลง ทูลว่า ศาลาใหม่นี้ยังไม่มีใครใช้ ขอพระองค์ทรงใช้ก่อน "
         "เพื่อประโยชน์สุขแก่ศากยะชาวกบิลพัสดุ์ตลอดกาลนาน",
    "3": "พระผู้มีพระภาคเจ้าทรงรับด้วยความนิ่ง ศากยะเหล่านั้นรู้ว่าพระองค์ทรงรับแล้ว จึงลุกขึ้นกราบ แล้วจัดแจง "
         "ปูอาสนะ เตรียมน้ำ แล้วทูลเชิญตามเวลาที่พระองค์ทรงเห็นสมควร",
    "4": "พระผู้มีพระภาคเจ้าทรงครองจีวร ถือบาตร เสด็จไปยังสัณฐาคารพร้อมภิกษุสงฆ์ ล้างพระบาทแล้วประทับ "
         "ศากยะชาวกบิลพัสดุ์ก็ล้างเท้าเข้าไปนั่งตามที่สมควร",
    "5": "พระผู้มีพระภาคเจ้าทรงแสดงธรรมแก่ศากยะชาวกบิลพัสดุ์ตลอดราตรีเกือบทั้งคืน แล้วตรัสกับท่านอานนท์ว่า "
         "อานนท์ เธอจงแสดงเสขปฏิปทา (ข้อปฏิบัติของผู้ยังต้องศึกษา) แก่ศากยะชาวกบิลพัสดุ์ หลังของเราเมื่อยล้า "
         "เราจะพัก พระผู้มีพระภาคเจ้าทรงปูสังฆาฏิสี่ชั้น นอนตะแคงขวาแบบสีหไสยา วางเท้าซ้อนเท้า มีสติ รู้ตัว "
         "ตั้งใจไว้ว่าจะลุกขึ้น",
    "6": "ท่านอานนท์กล่าวกับเจ้ามหานามะว่า มหานามะ อริยสาวกในธรรมวินัยนี้ เป็นผู้ถึงพร้อมด้วยศีล "
         "คุ้มครองทวารในอินทรีย์ รู้ประมาณในการบริโภคอาหาร หมั่นประกอบความเพียรเครื่องตื่น ประกอบด้วยสัปปุริสธรรม ๗ "
         "และได้ฌาน ๔ ตามปรารถนา ไม่ยาก ไม่ลำบาก",
    "7": "อริยสาวกเป็นผู้ถึงพร้อมด้วยศีลอย่างไร คือ เป็นผู้มีศีล สำรวมด้วยปาติโมกขสังวร ถึงพร้อมด้วยมารยาท "
         "และโคจร เห็นภัยในโทษแม้เล็กน้อย สมาทานศึกษาอยู่ในสิกขาบททั้งหลาย",
    "8": "อริยสาวกคุ้มครองทวารในอินทรีย์อย่างไร คือ เห็นรูปด้วยตาแล้ว ไม่ถือนิมิต ไม่ถืออนุพยัญชนะ "
         "สำรวมระวังจักขุนทรีย์ เมื่อไม่ได้สำรวมแล้ว อกุศลธรรมคืออภิชฌาและโทมนัสจะครอบงำได้ "
         "จึงปฏิบัติเพื่อความสำรวม ฟังเสียงด้วยหู ดมกลิ่นด้วยจมูก ลิ้มรสด้วยลิ้น ถูกต้องสัมผัสด้วยกาย "
         "รู้ธรรมด้วยใจแล้ว ก็สำรวมเช่นเดียวกัน",
    "9": "อริยสาวกรู้ประมาณในการบริโภคอาหารอย่างไร คือ พิจารณาโดยแยบคายแล้วบริโภคอาหาร ไม่ใช่เพื่อเล่น "
         "ไม่ใช่เพื่อมัวเมา ไม่ใช่เพื่อประดับตกแต่ง แต่เพียงเพื่อให้กายนี้ตั้งอยู่ได้ เพื่อความอยู่รอด "
         "เพื่อกำจัดความหิวเก่า ไม่ก่อความอึดอัดใหม่",
    "10": "อริยสาวกหมั่นประกอบความเพียรเครื่องตื่นอย่างไร คือ กลางวันชำระจิตจากธรรมเป็นเครื่องกั้นด้วยการเดินจงกรม "
          "และนั่ง กลางคืนยามต้นและยามสุดท้ายก็เช่นเดียวกัน ส่วนยามกลางของคืน นอนตะแคงขวาแบบสีหไสยา "
          "วางเท้าซ้อนเท้า มีสติ รู้ตัว ตั้งใจไว้ว่าจะลุกขึ้น",
    "11": "อริยสาวกประกอบด้วยสัปปุริสธรรม ๗ อย่างไร คือ เป็นผู้มีศรัทธา เชื่อการตรัสรู้ของพระตถาคตว่า "
          "พระผู้มีพระภาคเจ้านั้น เป็นพระอรหันต์ ตรัสรู้ชอบได้เอง ถึงพร้อมด้วยความรู้และความประพฤติ ไปดีแล้ว "
          "รู้แจ้งโลก เป็นผู้ฝึกคนที่ควรฝึกได้อย่างไม่มีใครยิ่งกว่า เป็นครูของเทวดาและมนุษย์ เป็นผู้รู้ ผู้ตื่น ผู้เบิกบาน "
          "เป็นผู้มีโชค ควรแก่การจำแนกธรรม",
    "12": "เป็นผู้มีหิริ (ละอาย) ต่อกายทุจริต วจีทุจริต มโนทุจริต ละอายต่ออกุศลธรรมทั้งหลาย",
    "13": "เป็นผู้มีโอตตัปปะ (เกรงกลัว) ต่อกายทุจริต วจีทุจริต มโนทุจริต เกรงกลัวต่ออกุศลธรรมทั้งหลาย",
    "14": "เป็นผู้ได้ยินได้ฟังมาก ทรงสุตะ สั่งสมสุตะ ธรรมทั้งหลายที่งามเบื้องต้น ท่ามกลาง และที่สุด "
          "เขาฟังมาก ทรงจำไว้ คล่องปาก ขึ้นใจ แทงตลอดด้วยความเห็น",
    "15": "เป็นผู้ปรารภความเพียรเพื่อละอกุศลธรรม เพื่อยังกุศลธรรมให้เกิด มีความเข้มแข็ง ไม่ทอดธุระในกุศลธรรม",
    "16": "เป็นผู้มีสติ มีสติสัมปชัญญะอันเลิศ ระลึกได้แม้สิ่งที่ทำและพูดไว้นานแล้ว",
    "17": "เป็นผู้มีปัญญา ประกอบด้วยปัญญาที่เห็นความเกิดดับ เป็นอริยะ ชำแรกกิเลส ให้ถึงความสิ้นทุกข์โดยชอบ "
          "นี้คือสัปปุริสธรรม ๗",
    "18": "อริยสาวกได้ฌาน ๔ อย่างไร คือ สงัดจากกามและอกุศลธรรม บรรลุปฐมฌาน ทุติยฌาน ตติยฌาน "
          "และจตุตถฌาน ตามลำดับ",
    "19": "มหานามะ เมื่อใดอริยสาวกเป็นผู้ถึงพร้อมด้วยศีล คุ้มครองทวาร รู้ประมาณอาหาร หมั่นตื่น "
          "ประกอบด้วยสัปปุริสธรรม ๗ และได้ฌาน ๔ อย่างนี้ เปรียบเหมือนแม่ไก่นอนกกไข่ ๘ ฟอง ๑๐ ฟอง หรือ ๑๒ ฟอง "
          "อย่างถูกต้อง แม้แม่ไก่จะไม่คิดว่า ลูกไก่ของเราจงเจาะเปลือกไข่ออกมาโดยสวัสดี แต่ลูกไก่ก็สามารถเจาะเปลือก "
          "ออกมาได้โดยสวัสดี ฉันใด อริยสาวกผู้ประกอบด้วยธรรมเหล่านี้ ก็สามารถเจาะออก (บรรลุธรรม) ได้ ฉันนั้น",
    "20": "อริยสาวกนั้นอาศัยอุเบกขาสติปาริสุทธินี้ ระลึกชาติก่อนได้หลายชาติ คือ ชาติหนึ่ง สอง สาม สี่ ห้า สิบ ยี่สิบ "
          "สามสิบ สี่สิบ ห้าสิบ ร้อย พัน แสนชาติบ้าง หลายสังวัฏฏกัป วิวัฏฏกัป สังวัฏฏวิวัฏฏกัปบ้าง ว่า เราเคยเกิด "
          "ชื่ออย่างนั้น ตระกูลอย่างนั้น... นี้คือการเจาะออกครั้งแรก เหมือนลูกไก่เจาะเปลือกไข่",
    "21": "อริยสาวกนั้นอาศัยอุเบกขาสติปาริสุทธินี้ เห็นสัตว์ด้วยทิพจักษุอันบริสุทธิ์ ล่วงจักษุของมนุษย์ "
          "เห็นสัตว์จุติและเกิด ทั้งต่ำและสูง งามและไม่งาม ไปดีและไปชั่ว รู้ชัดตามกรรมของสัตว์ "
          "นี้คือการเจาะออกครั้งที่สอง",
    "22": "อริยสาวกนั้นอาศัยอุเบกขาสติปาริสุทธินี้ กระทำให้แจ้งซึ่งเจโตวิมุตติ ปัญญาวิมุตติ อันไม่มีอาสวะ "
          "เพราะอาสวะสิ้นไป ด้วยปัญญาอันยิ่งด้วยตนเอง นี้คือการเจาะออกครั้งที่สาม",
    "23": "มหานามะ ข้อที่อริยสาวกเป็นผู้ถึงพร้อมด้วยศีล คุ้มครองทวาร รู้ประมาณอาหาร หมั่นตื่น "
          "ประกอบด้วยสัปปุริสธรรม ๗ และได้ฌาน ๔ นี้เป็นจรณะ (ความประพฤติ) ของเธอ",
    "24": "ข้อที่อริยสาวกระลึกชาติก่อนได้ เห็นสัตว์ด้วยทิพจักษุ และทำอาสวะให้สิ้นแล้วบรรลุเจโตวิมุตติ ปัญญาวิมุตติ "
          "นี้เป็นวิชชา (ความรู้) ของเธอ",
    "25": "มหานามะ อริยสาวกนี้เรียกว่า ผู้ถึงพร้อมด้วยวิชชา ผู้ถึงพร้อมด้วยจรณะ ผู้ถึงพร้อมด้วยวิชชาและจรณะ "
          "ท้าวสหัมบดีพรหมได้กล่าวคาถานี้ไว้ว่า กษัตริย์เป็นเลิศในหมู่ชนผู้ถือตระกูล แต่ผู้ถึงพร้อมด้วยวิชชาและจรณะ "
          "เป็นเลิศกว่าเทวดาและมนุษย์ทั้งปวง",
    "26": "ครั้งนั้น พระผู้มีพระภาคเจ้าทรงลุกขึ้น ตรัสเรียกท่านอานนท์ว่า ดีแล้ว ๆ อานนท์ เธอแสดงเสขปฏิปทา "
          "แก่ศากยะชาวกบิลพัสดุ์ได้ดีแล้ว ท่านอานนท์กล่าวคำนี้แล้ว พระศาสดาทรงพอพระทัย "
          "ศากยะชาวกบิลพัสดุ์ก็ยินดีชื่นชมภาษิตของท่านอานนท์ (จบเสขสูตรที่ ๓)",
}
